export const PHOSPHOR_ICON_NAMES = PHOSPHOR_ICON_MANIFEST.map((entry) => entry.name);
const phosphorNames = new Set<string>(PHOSPHOR_ICON_NAMES);
export function isPhosphorIconName(value: unknown): value is (typeof PHOSPHOR_ICON_MANIFEST)[number]["name"] { return typeof value === "string" && phosphorNames.has(value); }
export function getPhosphorIconManifestEntry(value: string) { return PHOSPHOR_ICON_MANIFEST.find((entry) => entry.name === value); }
